const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1050,height:800}});
 const errors=[]; page.on('pageerror',e=>errors.push(e.message)); page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://localhost:3000');
 await page.locator('#startButton').click();
 await page.keyboard.down('ArrowRight');
 await page.waitForTimeout(500);
 await page.keyboard.up('ArrowRight');
 const result=await page.evaluate(()=>{
  const c=document.querySelector('canvas'),x=c.getContext('2d').getImageData(0,0,c.width,c.height).data;
  let minX=999,maxX=-1,minY=999,maxY=-1,n=0;
  for(let y=0;y<c.height;y++)for(let xx=0;xx<c.width;xx++){let i=(y*c.width+xx)*4;if(x[i]===239&&x[i+1]===96&&x[i+2]===127){minX=Math.min(minX,xx);maxX=Math.max(maxX,xx);minY=Math.min(minY,y);maxY=Math.max(maxY,y);n++}}
  return {bounds:[minX,minY,maxX,maxY],pixels:n,room:document.querySelector('#roomName').textContent,lives:document.querySelector('#lives').textContent};
 });
 await page.screenshot({path:'/tmp/opencode/after-right.png'});
 console.log(JSON.stringify({result,errors}));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

